#include "tests/support/socket/node_insertion_test_fixture.hpp"
using namespace node_insertion_test;
namespace {
void linked_shapes(){
    for(unsigned kind=0;kind<4;++kind){Fixture f;const auto p=kind&1?Fixture::previous:0,n=kind&2?Fixture::next:0;f.linked(p,n);
        const auto before_doc=f.document;const auto before_pool=f.objects[4];f.call();
        check(f.get(Fixture::parent+0x38)==(p?p:n)&&f.get(Fixture::parent+0x40)==(n?n:p),"cached old parent first/last reflect only-child,first,last and middle detach");
        check(!f.get(Fixture::child+0x10)&&!f.get(Fixture::child+0x48)&&!f.get(Fixture::child+0x50),"linked child next,previous,parent are cleared");
        check((!p||f.get(p+0x50)==n)&&(!n||f.get(n+0x48)==p),"live neighbors reconnect without destruction");
        check(f.document==before_doc&&f.objects[4]==before_pool&&f.nodes.tracks.empty(),"linked path skips document vector and pool entirely despite unmapped requested owner");f.expect_no_destroy();
    }
    {Fixture f;f.linked();f.omitted={{Fixture::child+8,8},{Fixture::child+0x60,8},{Fixture::doc,0x308},{Fixture::pool,0x80}};f.refresh();f.call();check(!f.get(Fixture::child+0x10)&&f.nodes.tracks.empty(),"linked path does not access document,pool or child document/pool fields");}
    {Fixture f;f.linked(Fixture::child,Fixture::child);f.call(Fixture::child,Fixture::child);check(!f.get(Fixture::child+0x10)&&!f.get(Fixture::child+0x48)&&!f.get(Fixture::child+0x50)&&f.nodes.tracks.empty(),"self-linked child follows ordered stores without owner/self guard");}
}
void linked_aliases_and_failures(){
    {Fixture f;f.linked(0,Fixture::next);std::array<std::uint8_t,8> shared{};put(shared,0,Fixture::child);f.extras={{Fixture::parent+0x38,shared},{Fixture::parent+0x40,shared}};f.refresh();f.call();check(word(shared,0)==Fixture::next,"parent.last is reread after aliased parent.first store rather than prefetched");check(!f.get(Fixture::next+0x48),"remaining neighbor sees fresh child.previous");}
    {Fixture f;constexpr std::uintptr_t following=0x200000000ULL;f.extras={{following,f.objects[3]}};f.refresh();f.linked(Fixture::previous,following);std::array<std::uint8_t,16> shifted{};put(shifted,0,following);f.extras.push_back({Fixture::child+0x50,std::span(shifted).first(8)});f.extras.push_back({Fixture::previous+0x50,std::span(shifted).subspan(4,8)});f.refresh();f.set(following+0x48,0xfeed);f.call();check(f.get(following+0x48)==0xfeed,"previous.next partial alias changes child.next to zero; next pointer must be reread before its branch");check(!f.get(Fixture::child+0x50)&&!f.get(Fixture::child+0x10),"ordered final clears preserve aliased detach outcome");}
    {Fixture f;f.linked(Fixture::previous,Fixture::next);f.extras={{Fixture::previous+0x50,std::span(f.objects[0]).subspan(0x48,8)}};f.refresh();f.call();check(f.get(Fixture::next+0x48)==Fixture::next,"next.previous receives fresh child.previous after previous.next aliases it");}
    {Fixture f;f.linked();f.omitted={{Fixture::parent+0x40,8}};f.refresh();unmapped([&]{f.call();});check(!f.get(Fixture::parent+0x38)&&f.get(Fixture::child+0x10)==Fixture::parent,"missing live last mapping retains only earlier first-store prefix,without rollback");check(f.nodes.tracks.empty(),"mapping failure does not enter pool path");}
    {Fixture f;f.linked(Fixture::previous,Fixture::next);f.omitted={{Fixture::previous+0x50,8}};f.refresh();unmapped([&]{f.call();});check(f.get(Fixture::child+0x48)==Fixture::previous&&f.get(Fixture::child+0x50)==Fixture::next&&f.get(Fixture::child+0x10)==Fixture::parent,"failed neighbor store does not prematurely clear child links");}
}
void unlinked_vector(){
    for(std::uint32_t count:{0U,0x80000000U,0xffffffffU}){Fixture f;f.set(Fixture::doc+0x104,count,4);f.omitted={{Fixture::doc+0xa8,8},{Fixture::entries,32}};f.refresh();const auto before=f.objects[0];f.call();check(f.get(Fixture::doc+0x104,4)==count&&f.objects[0]==before,"nonpositive signed count skips entries and preserves all child bytes");check(f.nodes.tracks.size()==1&&f.nodes.tracks[0].target==Fixture::target&&f.nodes.tracks[0].pool==Fixture::pool,"every skipped-search path forwards live pool/track identity");f.expect_no_destroy();}
    for(int match:{-1,0,1,2}){Fixture f;f.set(Fixture::doc+0x104,3,4);const std::array<std::uintptr_t,3> values{0x1111,0x2222,0x3333};for(unsigned i=0;i<3;++i)f.set(Fixture::entries+i*8,static_cast<int>(i)==match?Fixture::child:values[i]);const auto child_before=f.objects[0];f.call();check(f.get(Fixture::doc+0x104,4)==(match<0?3U:2U),"outstanding count decremented only on matching child");check(match<0||f.get(Fixture::entries+static_cast<unsigned>(match)*8)==(match==2?Fixture::child:values[2]),"matching slot replaced from cached-bound tail, including already-last entry");check(f.objects[0]==child_before&&f.nodes.tracks.size()==1,"unlinked path keeps child fields/stale tail and always tracks once");f.expect_no_destroy();}
    {Fixture f;constexpr std::uintptr_t special=0x2200000002ULL,replacement=0x4400000009ULL;f.extras={{special,f.objects[0]},{Fixture::entries,std::span(f.document).subspan(0x104,8)}};f.refresh();f.set(special+8,Fixture::doc);f.set(special+0x10,0);f.set(special+0x60,Fixture::pool);f.set(Fixture::entries,special);f.set(Fixture::entries+8,replacement);f.call(special);check(f.get(Fixture::doc+0x104,4)==8,"swap aliases count: DEC rereads replacement lowDWORD9 and writes8 rather than cached2-minus1");check(f.nodes.tracks.size()==1&&f.nodes.tracks[0].pool==Fixture::pool,"count alias still reaches tracking without node destruction");}
    {Fixture f;f.set(Fixture::doc+0x104,2,4);f.set(Fixture::child,Fixture::table);f.set(Fixture::child+0x60,Fixture::child);f.extras={{Fixture::entries,std::span(f.objects[0]).subspan(0x60,8)}};f.refresh();f.set(Fixture::entries+8,Fixture::pool);f.call();check(f.nodes.tracks.size()==1&&f.nodes.tracks[0].pool==Fixture::pool,"pool pointer reload follows vector swap that aliases child.pool");}
}
void unlinked_failures(){
    {Fixture f;f.set(Fixture::doc+0x104,2,4);f.set(Fixture::entries,Fixture::child);f.set(Fixture::entries+8,0xabcd);f.nodes.track_hook=[](const auto&){throw Failure{};};fails([&]{f.call();});check(f.get(Fixture::entries)==0xabcd&&f.get(Fixture::doc+0x104,4)==1&&f.nodes.tracks.size()==1,"track failure retains committed vector swap/count prefix without rollback/free");f.expect_no_destroy();}
    {Fixture f;f.set(Fixture::doc+0x104,1,4);f.set(Fixture::entries,0x9999);f.omitted={{Fixture::entries,8}};f.refresh();unmapped([&]{f.call();});check(f.get(Fixture::doc+0x104,4)==1&&f.nodes.tracks.empty(),"missing search entry fails before track without changing count");}
    {Fixture f;f.set(Fixture::doc+0x104,1,4);f.set(Fixture::entries,Fixture::child);f.omitted={{Fixture::pool,8}};f.refresh();unmapped([&]{f.call();});check(f.get(Fixture::doc+0x104,4)==0&&f.nodes.tracks.empty(),"missing live pool-vtable mapping preserves completed vector removal");}
    {Fixture f;f.omitted={{Fixture::child+0x10,8}};f.refresh();unmapped([&]{f.call();});check(f.nodes.tracks.empty(),"missing initial parent field produces no lower calls");}
    {Fixture f;unmapped([&]{f.call(0);});check(f.nodes.tracks.empty(),"no invented child-null guard suppresses bounded initial read failure");}
}
}
int main(){try{linked_shapes();linked_aliases_and_failures();unlinked_vector();unlinked_failures();std::cout<<"PASS: "<<checks<<" node-insertion core checks; ignored owner,ordered detach,physical aliases,signed vector bounds/live unsigned tail,swap-liveDEC and failure prefixes; native ABI/EH open\n";}catch(const std::exception& e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}catch(...){std::cerr<<"FAIL after "<<checks<<" checks\n";return 1;}}
